def b91decode(strng):
    b = 0
    n = 0
    out = []
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'
    for c in strng:
        if c not in alphabet:
            continue
        v = alphabet.index(c)
        if v < 0 or v > 90:
            continue
        b |= v * (1 << n)
        n += 13 if (n & 7) + 7 < 13 else 7
        while n > 7:
            out.append(b & 255)
            b >>= 8
            n -= 8
    if n > 0:
        out.append(b % 256)
    return bytes(out)

