class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        trailing_zeros = [0] * n
        for i in range(n):
            count = 0
            for j in range(n - 1, -1, -1):
                if grid[i][j] == 0:
                    count += 1
                else:
                    break
            trailing_zeros[i] = count
        swaps = 0
        for i in range(n):
            required = n - i - 1
            if trailing_zeros[i] >= required:
                continue
            j = i + 1
            while j < n and trailing_zeros[j] < required:
                j += 1
            if j == n:
                return -1
            while j > i:
                trailing_zeros[j], trailing_zeros[j - 1] = trailing_zeros[j - 1], trailing_zeros[j]
                swaps += 1
                j -= 1
        return swaps

